  "idea_id": "P06",
  "verdict": "kill",
  "tests": [
    {
      "id": "R001",
      "result": "pass",
      "evidence": "The idea is a client app displaying content to the user themselves; it does not file on a customer's behalf, handle protected health data, give licensed advice, or require the operator to hold a license.",
      "source_url": null
    },
    {
      "id": "T2",
      "result": "fail",
      "evidence": "The core function (retrieving group posts) depends entirely on Facebook's platform access. Meta discontinued the entire Facebook Groups API on April 22, 2024, removing third-party ability to read group feeds. Any workaround (scraping with user session cookies) is not a sanctioned API and violates Facebook's Platform Terms, which prohibit unauthorized automated data collection. This is a single third party (Meta) that can and has already revoked the exact access this idea requires.",
      "source_url": "https://techcrunch.com/2024/02/05/meta-cuts-off-third-party-access-to-facebook-groups-leaving-developers-and-customers-in-disarray/"
    },
    {
      "id": "T3",
      "result": "pass",
      "evidence": "No physical inventory, storage, or shipping is involved; this is a software content client.",
      "source_url": null
    },
    {
      "id": "T7",
      "result": "pass",
      "evidence": "No hardware manufacturing, fleets, or facilities required; a content client is buildable by a solo operator with standard cloud/app infra.",
      "source_url": null
    }
  ],
  "flags": [
    { "id": "T5", "evidence": "If built via scraping/session automation instead of API, Facebook's anti-scraping detection and account bans would likely require ongoing manual maintenance and support per user session, which does not scale automatically." },
    { "id": "T6", "evidence": "Even if a scraping-based MVP could launch within 90 days, sustained access is fragile given Meta's active enforcement against third-party Groups tools, undermining a durable path to paying customers." }
  ],
  "competitors": [
    {
      "name": "fbtool (Martin's corner on the web)",
      "url": "https://harizanov.com/2026/08/turning-facebook-groups-into-a-daily-digest/",
      "relationship": "direct",
      "pricing": null,
      "evidence": "Author explicitly built a browser-automation scraper because 'Facebook has no API for groups' and existing scraping services require uploading session cookies to third-party clouds, confirming no sanctioned API path exists."
    },
    {
      "name": "Not for You (browser extension)",
      "url": "https://notforyou.app/facebook",
      "relationship": "adjacent",
      "pricing": "free",
      "evidence": "Free extension that switches Facebook's native UI to its own built-in 'Feeds' chronological view (friends/groups/pages) rather than pulling data via an external API, sidestepping the Groups API deprecation by just toggling Facebook's own feature."
    },
    {
      "name": "Facebook native 'Feeds' tab",
      "url": "https://www.buzzfeednews.com/article/katienotopoulos/facebook-chronological-home-feed",
      "relationship": "direct",
      "pricing": "free (built into Facebook)",
      "evidence": "Facebook itself launched a native chronological 'Feeds' view covering Friends, Groups, and Pages in 2022, directly overlapping with the idea's value proposition."
    },
    {
      "name": "fb-groups-sort (Tampermonkey script)",
      "url": "https://github.com/jonastheis/fb-groups-sort/",
      "relationship": "adjacent",
      "pricing": "free/open-source",
      "evidence": "A userscript that re-sorts Facebook group posts by date within the existing Facebook web session, avoiding any API dependency."
    }
  ],
  "queries": {
    "exa": [
      "third-party app shows Facebook group posts chronologically without algorithm",
      "Facebook API access revoked third party client app"
    ],
    "brave": [
      "Facebook Graph API groups feed access third party app policy",
      "app to view Facebook groups chronological feed no algorithm",
      "Facebook groups API discontinued 2024 developers third party apps shut down"
    ]
  },
  "proposed_variant": {
    "idea": "A browser extension or userscript that runs inside the user's authenticated Facebook session (not via the Graph API) to re-sort and filter the native Facebook web UI to show only chronological posts from groups the user belongs to, similar to existing tools like Not for You or fb-groups-sort.",
    "reason": "This avoids dependency on the deprecated Facebook Groups API by operating client-side within the user's own browser session against the rendered page, which several existing free tools already do, though it still carries ToS and maintenance fragility risk as Facebook changes its markup."
  },
